// Package tsgo is the runtime support library for code generated by typespec-go.
//
// It is deliberately small: generic JSON codecs, Nullable, TypeSpec scalar types without a
// standard-library equivalent, validation error collection and strict-server helpers.
// It depends only on the Go standard library.
package tsgo

import "encoding/json"

// Nullable holds either an explicit JSON null or a value of type T.
//
// It is used for TypeSpec types of the form `T | null`. Combined with a pointer for optional
// properties it distinguishes all states of `prop?: T | null`:
//
//	nil                      → property absent
//	&Nullable{} (Null())     → property present with JSON null
//	&Nullable{...} (Value(v)) → property present with a value
//
// The value is stored behind a pointer so recursive types such as `next: Node | null` are valid Go.
type Nullable[T any] struct {
	v *T
}

// Null returns a Nullable holding JSON null.
func Null[T any]() Nullable[T] { return Nullable[T]{} }

// Value returns a Nullable holding v.
func Value[T any](v T) Nullable[T] { return Nullable[T]{v: &v} }

// IsNull reports whether n holds JSON null.
func (n Nullable[T]) IsNull() bool { return n.v == nil }

// Get returns the value and true, or the zero value and false when n is null.
func (n Nullable[T]) Get() (T, bool) {
	if n.v == nil {
		var zero T
		return zero, false
	}
	return *n.v, true
}

// MustGet returns the value and panics if n is null.
func (n Nullable[T]) MustGet() T {
	if n.v == nil {
		panic("tsgo: Nullable is null")
	}
	return *n.v
}

// Ptr returns a pointer to the held value, or nil when n is null. Mutations through the pointer
// are visible to every copy of n.
func (n Nullable[T]) Ptr() *T { return n.v }

// Ptr returns a pointer to v. It is a convenience for populating optional properties.
func Ptr[T any](v T) *T { return &v }

// MarshalJSON encodes null or the value with encoding/json. Generated code does not use this
// method; it uses NullableCodec so that TypeSpec encodings are honoured.
func (n Nullable[T]) MarshalJSON() ([]byte, error) {
	if n.v == nil {
		return []byte("null"), nil
	}
	return json.Marshal(*n.v)
}

// UnmarshalJSON decodes null or a value with encoding/json.
func (n *Nullable[T]) UnmarshalJSON(data []byte) error {
	if isJSONNull(data) {
		n.v = nil
		return nil
	}
	var v T
	if err := json.Unmarshal(data, &v); err != nil {
		return err
	}
	n.v = &v
	return nil
}
